/bin/bash -lc "node --input-type=module <<'NODE'
const responses = []
for (let i = 0; i < 2; i++) {
  const response = await fetch('http://localhost:3097/')
  const html = await response.text()
  const details = html.match(/Request ([0-9a-f-]{36}) generated at (["'^<]+) '"\\(sample (["'^)]+)'"\\)/)
  responses.push({ status: response.status, navigation: html.includes('<nav>Operations</nav>'), fallback: html.includes('Loading request details'), details: details?.slice(1) })
  await new Promise(resolve => setTimeout(resolve, 100))
}
console.log(JSON.stringify(responses, null, 2))
NODE"

